#!/usr/bin/env python3
"""Run xTB/sTDA from the heavy-atom coordinates generated by diffusion.

RDKit is used only to sanitize the generated graph, reject charged/open-shell
structures for this closed-shell benchmark, and place missing hydrogen atoms.
The generated heavy-atom coordinates are never embedded or force-field
optimized before xTB receives them.
"""

from __future__ import annotations

import argparse
import csv
import json
import os
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

import numpy as np
from rdkit import Chem
from rdkit.Chem import rdMolDescriptors

from joint_xtb_stda_pipeline import aggregate, run_one


PREPARATION_CONFIG = {
    "schema_version": 2,
    "coordinate_policy": "preserve_diffusion_heavy_atom_coordinates",
    "hydrogen_policy": "Chem.AddHs(addCoords=True)",
    "rdkit_embedding": False,
    "rdkit_force_field_optimization": False,
    "require_closed_shell": True,
    "require_net_charge_zero": True,
}


def _property(molecule: Chem.Mol, key: str, default: object = "") -> object:
    return molecule.GetProp(key) if molecule.HasProp(key) else default


def prepare_diffusion_coordinates(source: Path, output: Path) -> list[dict[str, object]]:
    output.mkdir(parents=True, exist_ok=True)
    manifest = output / "manifest.csv"
    config_path = output / "preparation_config.json"
    if manifest.exists() and any(output.glob("generated_*.sdf")):
        if not config_path.exists() or json.loads(config_path.read_text()) != PREPARATION_CONFIG:
            raise RuntimeError(
                "existing input cache does not preserve diffusion coordinates; "
                "choose a new output directory"
            )
        with manifest.open(newline="") as handle:
            return list(csv.DictReader(handle))

    rows: list[dict[str, object]] = []
    supplier = Chem.SDMolSupplier(str(source), removeHs=False, sanitize=True)
    for index, molecule in enumerate(supplier):
        name = f"generated_{index:06d}"
        row: dict[str, object] = {
            "name": name,
            "source_index": index,
            "status": "",
            "smiles": "",
            "formal_charge": "",
            "uhf": "",
            "heavy_atoms": "",
            "rings": "",
            "aromatic_rings": "",
            "elements": "",
            "hydrogens": "",
            "source_is_3d": "",
            "source_coord_rms_radius": "",
            "heavy_coord_max_abs_delta": "",
            "error": "",
            "generation_index": "",
            "target_s1_eV": "",
            "s1_range": "",
            "requested_atom_count": "",
            "condition_name": "",
            "condition_range": "",
            "target_value": "",
        }
        try:
            if molecule is None:
                raise ValueError("RDKit read failed")
            row["generation_index"] = _property(molecule, "generation_index", index)
            row["target_s1_eV"] = _property(molecule, "target_property")
            row["s1_range"] = _property(molecule, "s1_range")
            row["requested_atom_count"] = _property(molecule, "requested_atom_count")
            row["condition_name"] = _property(molecule, "condition_name")
            row["condition_range"] = _property(molecule, "condition_range")
            row["target_value"] = _property(molecule, "target_property")

            base = Chem.Mol(molecule)
            if any(atom.GetAtomicNum() == 1 for atom in base.GetAtoms()):
                raise ValueError("expected a hydrogen-free heavy-atom diffusion sample")
            Chem.SanitizeMol(base)
            if base.GetNumConformers() == 0:
                raise ValueError("diffusion sample has no conformer")

            source_conf = base.GetConformer(0)
            source_xyz = np.asarray(source_conf.GetPositions(), dtype=np.float64).copy()
            if source_xyz.shape != (base.GetNumAtoms(), 3):
                raise ValueError(f"unexpected coordinate shape: {source_xyz.shape}")
            if not np.isfinite(source_xyz).all():
                raise ValueError("diffusion coordinates contain NaN or infinity")
            centered = source_xyz - source_xyz.mean(axis=0, keepdims=True)
            rms_radius = float(np.sqrt(np.mean(np.sum(centered * centered, axis=1))))
            if rms_radius <= 1.0e-6:
                raise ValueError("degenerate diffusion coordinates")

            charge = sum(atom.GetFormalCharge() for atom in base.GetAtoms())
            uhf = sum(atom.GetNumRadicalElectrons() for atom in base.GetAtoms())
            if charge:
                raise ValueError(f"net-charged molecule rejected before xTB: charge={charge}")
            if uhf:
                raise ValueError(f"open-shell molecule rejected before xTB: UHF={uhf}")

            smiles = Chem.MolToSmiles(base, canonical=True, isomericSmiles=False)
            molecule_3d = Chem.AddHs(base, explicitOnly=False, addCoords=True)
            if molecule_3d.GetNumConformers() == 0:
                raise ValueError("Chem.AddHs removed the diffusion conformer")
            output_xyz = np.asarray(
                molecule_3d.GetConformer(0).GetPositions(), dtype=np.float64
            )
            if not np.isfinite(output_xyz).all():
                raise ValueError("hydrogenated coordinates contain NaN or infinity")
            heavy_delta = float(
                np.max(np.abs(output_xyz[: base.GetNumAtoms()] - source_xyz))
            )
            if heavy_delta > 1.0e-7:
                raise ValueError(
                    "Chem.AddHs changed generated heavy-atom coordinates: "
                    f"max_abs_delta={heavy_delta:.3e}"
                )

            molecule_3d.SetProp("_Name", name)
            molecule_3d.SetProp("SMILES", smiles)
            molecule_3d.SetProp("coordinate_source", "diffusion")
            molecule_3d.SetIntProp("formal_charge", charge)
            molecule_3d.SetIntProp("uhf", uhf)
            writer = Chem.SDWriter(str(output / f"{name}.sdf"))
            writer.write(molecule_3d)
            writer.close()
            row.update(
                status="ok",
                smiles=smiles,
                formal_charge=charge,
                uhf=uhf,
                heavy_atoms=base.GetNumHeavyAtoms(),
                rings=rdMolDescriptors.CalcNumRings(base),
                aromatic_rings=rdMolDescriptors.CalcNumAromaticRings(base),
                elements=",".join(
                    sorted({atom.GetSymbol() for atom in base.GetAtoms()})
                ),
                hydrogens=molecule_3d.GetNumAtoms() - base.GetNumAtoms(),
                source_is_3d=bool(source_conf.Is3D()),
                source_coord_rms_radius=rms_radius,
                heavy_coord_max_abs_delta=heavy_delta,
            )
        except Exception as exc:
            row.update(status="failed", error=f"{type(exc).__name__}: {exc}")
        rows.append(row)
        if (index + 1) % 50 == 0:
            print(
                json.dumps({"event": "prepare", "completed": index + 1}),
                flush=True,
            )

    if not rows:
        raise RuntimeError("no molecules in source SDF")
    with manifest.open("w", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)
    config_path.write_text(json.dumps(PREPARATION_CONFIG, indent=2) + "\n")
    summary = {
        "total": len(rows),
        "exported": sum(row["status"] == "ok" for row in rows),
        "failed": sum(row["status"] != "ok" for row in rows),
        "max_heavy_coord_abs_delta": max(
            (
                float(row["heavy_coord_max_abs_delta"])
                for row in rows
                if row["status"] == "ok"
            ),
            default=None,
        ),
        **PREPARATION_CONFIG,
    }
    (output / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    return rows


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--input-sdf", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("--xtb-env", type=Path, required=True)
    parser.add_argument("--workers", type=int, default=4)
    parser.add_argument("--threads", type=int, default=1)
    parser.add_argument("--target-s1", type=float, required=True)
    parser.add_argument("--target-t1", type=float, required=True)
    args = parser.parse_args()
    if args.workers < 1 or args.threads != 1:
        raise ValueError("workers must be positive and threads must remain 1")

    args.output_dir.mkdir(parents=True, exist_ok=True)
    inputs = args.output_dir / "inputs"
    work = args.output_dir / "work"
    work.mkdir(exist_ok=True)
    metadata = prepare_diffusion_coordinates(args.input_sdf, inputs)
    files = sorted(inputs.glob("generated_*.sdf"))

    environment = os.environ.copy()
    environment["PATH"] = (
        str(args.xtb_env / "bin")
        + ":/home/jovyan/cpu-only-1-datavol-1/software/xtb4stda_home/exe:"
        + environment["PATH"]
    )
    environment["LD_LIBRARY_PATH"] = (
        str(args.xtb_env / "lib")
        + ":"
        + environment.get("LD_LIBRARY_PATH", "")
    )
    environment["XTB4STDAHOME"] = (
        "/home/jovyan/cpu-only-1-datavol-1/software/xtb4stda_home"
    )
    environment["OMP_STACKSIZE"] = "2G"
    for key in (
        "OMP_NUM_THREADS",
        "MKL_NUM_THREADS",
        "OPENBLAS_NUM_THREADS",
        "NUMEXPR_NUM_THREADS",
        "BLIS_NUM_THREADS",
        "VECLIB_MAXIMUM_THREADS",
    ):
        environment[key] = "1"

    started = time.time()
    with ThreadPoolExecutor(max_workers=args.workers) as pool:
        futures = {
            pool.submit(run_one, path, work, environment): path for path in files
        }
        with (work / "progress.jsonl").open("a") as progress:
            for completed, future in enumerate(as_completed(futures), 1):
                result = future.result()
                progress.write(json.dumps(result) + "\n")
                progress.flush()
                print(
                    json.dumps(
                        {
                            "event": "result",
                            "completed": completed,
                            "total": len(files),
                            "name": result["name"],
                            "status": result["status"],
                            "s1": result.get("s1_energy_eV"),
                            "t1": result.get("t1_energy_eV"),
                            "elapsed_s": time.time() - started,
                        }
                    ),
                    flush=True,
                )
    print(
        json.dumps(
            {
                "event": "complete",
                **aggregate(work, metadata, args.target_s1, args.target_t1),
            },
            indent=2,
        ),
        flush=True,
    )


if __name__ == "__main__":
    main()
